import {esc,parseSbom} from './core.js';import {strictJSON,compareConfigs,compareComponents} from './firmware-compare.js';
export function createFirmwareCompareUI(ui){function compare(){const p=ui.project(),deviceId=p.deviceId,rows=p.evidence.filter(e=>e.deviceId===deviceId&&e.size<=1024*1024);if(rows.length<2)throw Error('Import or inspect two configuration/SBOM originals under 1 MiB first.');ui.showDialog('Compare structured originals',ui.selectField('Comparison','mode',['JSON configuration','INI / key=value','Literal .env','SBOM'],'JSON configuration',true)+['before','after'].map((k,i)=>`<label class="field">${k}<select name="${k}">${rows.map((e,j)=>`<option value="${e.id}" ${j===(i?rows.length-1:0)?'selected':''}>${esc(e.title)}</option>`).join('')}</select></label>`).join(''),data=>{const a=rows.find(e=>e.id===data.get('before')),b=rows.find(e=>e.id===data.get('after'));if(a===b)throw Error('Choose different originals.');const mode=data.get('mode'),result=mode==='SBOM'?compareComponents(parseSbom(strictJSON(ui.rawText(a))),parseSbom(strictJSON(ui.rawText(b)))):compareConfigs(ui.rawText(a),ui.rawText(b),mode==='JSON configuration'?'JSON':mode==='Literal .env'?'ENV':'INI');const record={format:'probe-structured-comparison-v1',mode,before:{evidenceId:a.id,sha256:a.hash},after:{evidenceId:b.id,sha256:b.hash},result};setTimeout(()=>ui.showDialog('Structured comparison',`<p class="notice">${esc(result.limitation)}</p><p class="muted spaced">${result.rows.length} changes. Sensitive key candidates are masked. Review other values before sharing.</p><div class="table-wrap spaced"><table><thead><tr><th>Key / component</th><th>Change</th><th>Before</th><th>After</th></tr></thead><tbody>${result.rows.slice(0,200).map(r=>`<tr><td class="break-word">${esc(r.key)}</td><td>${esc(r.change)}</td><td class="break-word">${esc(r.before)}</td><td class="break-word">${esc(r.after)}</td></tr>`).join('')||'<tr><td colspan="4">No parsed changes.</td></tr>'}</tbody></table></div><p class="muted">First 200 changes shown; saved result includes all changes.</p>`,async()=>{if(ui.project()!==p||p.deviceId!==deviceId)throw Error('Device changed.');const e=await ui.evidenceFromFile(new File([JSON.stringify(record,null,2)],'structured-comparison.json',{type:'application/json'}),'Structured comparison','Original references and hashes; candidate sensitive values masked.',deviceId);if(ui.project()!==p||p.deviceId!==deviceId)throw Error('Device changed.');p.evidence.push(e);ui.changed('Structured comparison preserved.');},'Save comparison evidence'),0);},'Compare');}return {button:()=>ui.button('Compare config / SBOM','structured-compare','small'),async action(name){if(name!=='structured-compare')return false;compare();return true;}};}
